async function startPayment(amount, description){
  var e = (typeof event !== "undefined" && event && event.target) ? event.target : null;
  if(e){ e.textContent = "Processing..."; e.disabled = true; }
  try{
    var r = await fetch("/api/create-order", {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({amount:amount, description:description})});
    var d = await r.json();
    if(d.success && d.approvalUrl){
      try{ sessionStorage.setItem("pay_order", d.orderId); sessionStorage.setItem("pay_amount", String(amount)); sessionStorage.setItem("pay_name", description); }catch(err){}
      if(description && description.indexOf("起名") >= 0){ try{ sessionStorage.setItem("name_pending", "1"); }catch(err){} }
      window.location.href = d.approvalUrl;
    }else{
      startPayPalFallback(amount, description);
    }
  }catch(err){
    startPayPalFallback(amount, description);
  }
}

function startPayPalFallback(amount, description){
  try{
    sessionStorage.setItem("pay_fallback", "1");
    sessionStorage.setItem("pay_amount", String(amount));
    sessionStorage.setItem("pay_name", description || "周易起名");
    sessionStorage.setItem("name_pending", "1");
  }catch(err){}
  window.location.href = "https://paypal.me/jishinet/" + amount;
}

(function(){
  var p = new URLSearchParams(window.location.search);
  if(p.get("payment") === "success"){
    var o = "";
    try{ o = sessionStorage.getItem("pay_order") || ""; }catch(err){}
    if(o){
      fetch("/api/capture-order", {method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify({orderId:o})})
        .then(function(r){ return r.json(); })
        .then(function(d){
          if(d.success){
            try{
              localStorage.setItem("js_paid", "true");
              if(sessionStorage.getItem("name_pending")){ renderSavedNameReport(); sessionStorage.removeItem("name_pending"); }
              sessionStorage.removeItem("pay_order"); sessionStorage.removeItem("pay_amount"); sessionStorage.removeItem("pay_name");
            }catch(err){}
            var m = document.createElement("div");
            m.style.cssText = "position:fixed;top:50%;left:50%;transform:translate(-50%,-50%);background:#1a8a1a;color:#fff;padding:1rem 2rem;border-radius:8px;z-index:99999;font-size:1rem";
            m.textContent = "Payment successful! Report unlocked.";
            document.body.appendChild(m);
            setTimeout(function(){ try{ m.remove(); }catch(err){} }, 2500);
          }
        });
    }
  } else if(p.get("payment") === "cancel"){
    alert("Payment cancelled");
  }
})();


function confirmManualPayment(){
  try{
    localStorage.setItem("js_paid", "true");
    sessionStorage.removeItem("pay_fallback");
    sessionStorage.removeItem("name_pending");
  }catch(err){}
  renderSavedNameReport();
}

(function(){
  var fallback = "";
  try{ fallback = sessionStorage.getItem("pay_fallback") || ""; }catch(err){}
  if(fallback){
    var box = document.getElementById("nameResults");
    if(box){
      box.innerHTML = '<div style="padding:1rem;background:linear-gradient(135deg,#FFF8EC,#FDEBD2);border:1.5px solid #D4A030;border-radius:12px;box-shadow:0 4px 16px rgba(175,32,32,0.08);text-align:center">' +
        '<h2 style="font-size:1.05rem;color:#AF2020;margin-bottom:0.5rem">请在 PayPal 完成支付</h2>' +
        '<p style="font-size:0.85rem;color:#555;margin-bottom:0.8rem">支付完成后返回本页，点击下方按钮解锁完整周易起名报告。</p>' +
        '<button onclick="confirmManualPayment()" style="padding:0.6rem 1.2rem;background:#AF2020;color:#fff;border:none;border-radius:8px;cursor:pointer">我已支付，查看报告</button></div>';
    }
  }
})();

function showPaywall(){
  var h = '<div id="paywall-overlay" style="position:fixed;top:0;left:0;right:0;bottom:0;background:rgba(0,0,0,0.55);z-index:9999;display:flex;align-items:center;justify-content:center;padding:1rem">';
  h += '<div style="background:#fff;border-radius:12px;padding:2rem;max-width:420px;width:100%;text-align:center;box-shadow:0 10px 40px rgba(0,0,0,0.25)">';
  h += '<h2 style="font-size:1.2rem;color:#2E2E2E;margin-bottom:0.5rem">周易起名完整报告</h2>';
  h += '<p style="font-size:0.85rem;color:#888;margin-bottom:1rem">付费后显示八字五行补益、生肖宜忌、笔画数理、音形义与推荐名。</p>';
  h += '<div style="display:grid;gap:0.6rem;margin-bottom:1rem">';
  h += '<button onclick="closePaywall();startPayment(5,\'周易起名-基础\')" style="padding:0.7rem;background:#AF2020;color:#fff;border:none;border-radius:8px;cursor:pointer">$4.99 - 起名基础报告</button>';
  h += '<button onclick="closePaywall();startPayment(15,\'周易起名-专业\')" style="padding:0.7rem;background:#AF2020;color:#fff;border:none;border-radius:8px;cursor:pointer">$14.99 - 起名专业报告</button>';
  h += '</div>';
  h += '<p style="font-size:0.75rem;color:#aaa">通过 PayPal 支付，支持信用卡/借记卡</p>';
  h += '</div></div>';
  var d = document.createElement("div");
  d.innerHTML = h;
  document.body.appendChild(d.firstElementChild);
}

function closePaywall(){ var el = document.getElementById("paywall-overlay"); if(el) el.remove(); }

var ZODIAC_LIST = ["鼠","牛","虎","兔","龙","蛇","马","羊","猴","鸡","狗","猪"];
var ZODIAC_ELEM = {鼠:"水",牛:"土",虎:"木",兔:"木",龙:"土",蛇:"火",马:"火",羊:"土",猴:"金",鸡:"金",狗:"土",猪:"水"};
var ZODIAC_LIKE = {鼠:["金","水"],牛:["火","土"],虎:["水","木"],兔:["水","木"],龙:["火","土"],蛇:["木","火"],马:["木","火"],羊:["火","土"],猴:["金","水"],鸡:["金","土"],狗:["火","土"],猪:["金","水"]};
var ZODIAC_AVOID = {鼠:["土"],牛:["木"],虎:["金"],兔:["金"],龙:["木"],蛇:["水"],马:["水"],羊:["木"],猴:["火"],鸡:["木"],狗:["木"],猪:["土"]};
var LUCKY_STROKES = [1,3,5,7,8,11,13,15,16,17,18,21,23,24,25,29,31,32,33,35,37,39,41,45,47,48,52,57,61,63,65,67,68,81];

function getZodiacInfo(year){
  var z = ZODIAC_LIST[((year - 4) % 12 + 12) % 12];
  return {zodiac:z, element:ZODIAC_ELEM[z] || "土", like:ZODIAC_LIKE[z] || ["火","土"], avoid:ZODIAC_AVOID[z] || ["木"]};
}

function isLuckyStroke(n){ return LUCKY_STROKES.indexOf(n) >= 0; }

function getDesiredElements(params){
  try{
    if(typeof computeBazi === "function"){
      var r = computeBazi(params.year, params.month, params.day, params.hour < 0 ? 12 : params.hour, params.gender === "f" ? "F" : "M");
      if(r && r.elemCount){
        var min = 99;
        var keys = [];
        for(var k in r.elemCount){ keys.push(k); if(r.elemCount[k] < min) min = r.elemCount[k]; }
        var arr = [];
        for(var j = 0; j < keys.length; j++){ if(r.elemCount[keys[j]] <= min + 1) arr.push(keys[j]); }
        if(arr.length) return arr.slice(0, 3);
      }
    }
  }catch(err){}
  var y = params.year;
  var el = ["木","木","火","火","土","土","金","金","水","水"][((y - 4) % 10 + 10) % 10];
  return [el];
}

function getCharStrokes(ch){
  if(NAME_CHARS[ch] && NAME_CHARS[ch].s) return NAME_CHARS[ch].s;
  if(typeof getNameStrokes === "function") return getNameStrokes(ch);
  return 0;
}

function scoreChar(ch, desired, zodiacInfo){
  var info = NAME_CHARS[ch] || {w:"", s:0};
  var score = 0;
  if(desired.indexOf(info.w) >= 0) score += 12;
  if(zodiacInfo.like.indexOf(info.w) >= 0) score += 6;
  if(zodiacInfo.avoid.indexOf(info.w) >= 0) score -= 4;
  if(CHAR_MEANINGS[ch]) score += 6;
  var st = info.s || getCharStrokes(ch);
  if(isLuckyStroke(st)) score += 4;
  if(st > 0 && st <= 12) score += 2;
  if(st > 22) score -= 2;
  return score;
}

function analyzeNameSafe(name){
  var total = 0;
  var arr = [];
  for(var i = 0; i < name.length; i++){
    var ch = name[i];
    var st = getCharStrokes(ch);
    total += st;
    arr.push({char:ch, strokes:st});
  }
  var numIndex = ((total - 1) % 81 + 81) % 81 + 1;
  var elem = "水";
  if([1,2,11,12,21,22,31,32,41,42,51,52,61,62,71,72,81].indexOf(numIndex) >= 0) elem = "木";
  else if([3,4,13,14,23,24,33,34,43,44,53,54,63,64,73,74].indexOf(numIndex) >= 0) elem = "火";
  else if([5,6,15,16,25,26,35,36,45,46,55,56,65,66,75,76].indexOf(numIndex) >= 0) elem = "土";
  else if([7,8,17,18,27,28,37,38,47,48,57,58,67,68,77,78].indexOf(numIndex) >= 0) elem = "金";
  return {totalStrokes:total, numIndex:numIndex, elem:elem, charAnalysis:arr, strokeScore:isLuckyStroke(numIndex) ? 6 : 0};
}

function buildNameCandidates(params){
  var desired = getDesiredElements(params);
  var zodiacInfo = getZodiacInfo(params.year);
  var chars = [];
  for(var k in NAME_CHARS){ chars.push(k); if(chars.length >= 20000) break; }
  chars.sort(function(){ return Math.random() - 0.5; });
  var scored = [];
  for(var i = 0; i < chars.length; i++){
    var sc = scoreChar(chars[i], desired, zodiacInfo);
    if(sc > 0) scored.push({ch:chars[i], score:sc});
  }
  scored.sort(function(a,b){ return b.score - a.score; });
  var top = scored.slice(0, 60);
  var names = [];
  for(var a = 0; a < top.length; a++){
    for(var b = 0; b < top.length; b++){
      if(a === b) continue;
      var name = params.surname + top[a].ch + top[b].ch;
      var full = analyzeNameSafe(name);
      var score = top[a].score + top[b].score + full.strokeScore;
      names.push({name:name, c1:top[a].ch, c2:top[b].ch, score:score, info:full});
    }
  }
  names.sort(function(x,y){ return y.score - x.score; });
  return {desired:desired, zodiac:zodiacInfo, candidates:names.slice(0, 20)};
}

function charStyleText(ch){
  var st = getCharStrokes(ch);
  if(st <= 8) return "字形简洁、结构疏朗，视觉轻快";
  if(st <= 14) return "笔画适中、结构匀称，书写稳定";
  return "笔画较多、结构厚重，适合稳重气质";
}


function getAnnualFortune(params){
  var now = new Date();
  var y = now.getFullYear();
  var gz = (typeof yGz === "function") ? yGz(y) : null;
  var gan = gz && gz.s !== undefined ? gz.s : "";
  var zhi = gz && gz.b !== undefined ? gz.b : "";
  var el = "";
  var sx = "";
  try{ if(typeof ELEM !== "undefined" && ELEM[gan]) el = ELEM[gan]; }catch(err){}
  try{ if(typeof SX !== "undefined" && SX[zhi]) sx = SX[zhi]; }catch(err){}
  var desired = getDesiredElements(params);
  var score = desired.indexOf(el) >= 0 ? 5 : (el ? 2 : 3);
  var text = "\u4eca\u5e74\u662f" + y + "\u5e74\uff0c\u6d41\u5e74\u4e94\u884c\u5c5e" + (el || "\u7efc\u5408") + (sx ? "\uff0c\u751f\u8096\u4e3a" + sx : "") + "\u3002";
  if(score >= 5) text += "\u6d41\u5e74\u4e94\u884c\u4e0e\u516b\u5b57\u6240\u9700\u76f8\u5408\uff0c\u9002\u5408\u628a\u63e1\u673a\u4f1a\u3001\u63a8\u8fdb\u4e8b\u4e1a\u4e0e\u5bb6\u5ead\u8ba1\u5212\u3002";
  else if(score >= 3) text += "\u6d41\u5e74\u8fd0\u52bf\u603b\u4f53\u5e73\u7a33\uff0c\u5b9c\u7a33\u4e2d\u6c42\u8fdb\uff0c\u6ce8\u91cd\u5065\u5eb7\u548c\u4eba\u9645\u6c9f\u901a\u3002";
  else text += "\u6d41\u5e74\u4e94\u884c\u4e0e\u516b\u5b57\u6240\u9700\u6709\u6240\u504f\u5dee\uff0c\u5efa\u8bae\u8865\u8db3" + desired.join("\u3001") + "\uff0c\u91cd\u5927\u51b3\u7b56\u5b9c\u591a\u6838\u5bf9\u3002";
  return text;
}


function renderNameReportFromParams(params){
  var result = buildNameCandidates(params);
  var h = '<div style="margin-bottom:1rem;padding:1rem;background:linear-gradient(135deg,#FFF8EC,#FDEBD2);border:1.5px solid #D4A030;border-radius:12px;box-shadow:0 4px 16px rgba(175,32,32,0.08)">';
  h += '<h2 style="font-size:1.15rem;color:#AF2020;margin-bottom:0.5rem">周易起名完整报告</h2>';
  h += '<div style="font-size:0.72rem;color:#999;margin-bottom:0.5rem">报告编号：JS-' + Date.now().toString(36).toUpperCase() + ' · ' + new Date().toLocaleString() + ' · 周易起名报告</div>';
  h += '<p style="font-size:0.85rem;color:#555;line-height:1.8">';
  h += '八字五行补益：宜补 <b>' + result.desired.join("、") + '</b>；';
  h += '生肖宜忌：<b>' + result.zodiac.zodiac + '</b> 命主喜 ' + result.zodiac.like.join("、") + '，忌 ' + result.zodiac.avoid.join("、") + '；';
  h += '<br><b>流年运势：</b>' + getAnnualFortune(params) + '；';
  h += '笔画以 1、3、5、7、8、11、13、15、16、17、18、21、23、24、25、29、31、32、33、35、37、39、41、45、47、48、52、57、61、63、65、67、68、81 等数理为吉。';
  h += '</p></div>';
  h += '<div style="display:grid;gap:0.8rem">';
  for(var i = 0; i < result.candidates.length; i++){
    var c = result.candidates[i];
    var chars = c.info.charAnalysis;
    h += '<div style="padding:1rem;background:linear-gradient(135deg,#FFFDF8,#FBEFDD);border:1px solid #E3C58A;border-radius:12px">';
    h += '<div style="display:flex;align-items:center;justify-content:space-between;gap:0.5rem;flex-wrap:wrap">';
    h += '<span style="font-size:1.5rem;font-weight:800;color:#AF2020">' + c.name + '</span>';
    h += '<span style="font-size:0.75rem;color:#fff;background:#AF2020;padding:0.2rem 0.5rem;border-radius:4px">推荐 #' + (i+1) + '</span></div>';
    h += '<p style="font-size:0.82rem;color:#555;line-height:1.8;margin-top:0.5rem">';
    h += '总笔画 ' + c.info.totalStrokes + ' 画，数理 ' + c.info.numIndex + '，五行属 ' + c.info.elem + '；';
    for(var j = 0; j < chars.length; j++){
      var info = NAME_CHARS[chars[j].char] || {w:"", s:0};
      h += chars[j].char + '（' + (info.w || "综合") + '，' + chars[j].strokes + '画）：' + charStyleText(chars[j].char) + '；' + (CHAR_MEANINGS[chars[j].char] ? '字义：' + CHAR_MEANINGS[chars[j].char] : '字义：寓意积极、适合命名。') + '；';
    }
    h += '音形义建议：发音自然、字义积极，与姓氏组合后气韵平稳。';
    h += '</p></div>';
  }
  h += '</div>';
  h += '<p style="font-size:0.72rem;color:#999;margin-top:0.8rem">* 周易起名报告基于传统文化规则生成，仅供文化参考及娱乐用途。</p>';
  document.getElementById("nameResults").innerHTML = h;
  var rp = document.getElementById("reportPage");
  if(rp){ document.getElementById("rpSubtitle").textContent = "周易起名完整报告"; document.getElementById("rpContent").innerHTML = h; rp.className = "rp op"; }
}

function renderSavedNameReport(){
  var raw = "";
  try{ raw = localStorage.getItem("name_draft") || ""; }catch(err){}
  if(!raw) return false;
  try{
    var params = JSON.parse(raw);
    renderNameReportFromParams(params);
    return true;
  }catch(err){ return false; }
}


function getDreamCategory(text){
  var t = text || "";
  if(/[\u8d22\u94b1\u91d1\u9c7c\u6c34\u5bcc\u8d22]/.test(t)) return "\u8d22\u8fd0\u53c2\u8003";
  if(/[\u7231\u5a5a\u604b\u60c5\u82b1\u73ab\u7470\u9e33\u9e2f]/.test(t)) return "\u611f\u60c5\u53c2\u8003";
  if(/[\u5de5\u4f5c\u4e8b\u4e1a\u5347\u804c\u5b98\u9f99\u9a6c\u98de]/.test(t)) return "\u4e8b\u4e1a\u53c2\u8003";
  if(/[\u75c5\u4f24\u8840\u6b7b\u9b3c\u75db]/.test(t)) return "\u5065\u5eb7\u8b66\u793a";
  return "\u7efc\u5408\u53c2\u8003";
}

function searchDream(){
  var input = document.getElementById("dreamSearch");
  if(!input) return;
  var q = input.value.trim();
  var box = document.getElementById("dreamResults");
  if(!box) return;
  if(!q){ box.innerHTML = '<p style="color:#999;font-size:0.85rem">\u8bf7\u8f93\u5165\u68a6\u5883\u5173\u952e\u8bcd</p>'; return; }
  var results = DREAM_DATA.filter(function(item){
    return item.t.indexOf(q) >= 0 || item.keyword.indexOf(q) >= 0 || item.d.indexOf(q) >= 0;
  });
  if(results.length === 0){
    var h = '<div style="padding:1rem;background:#FFF8EC;border:1px solid #EAD9BE;border-radius:12px;margin-bottom:0.8rem"><p style="font-size:0.9rem;color:#6B4B1F;margin-bottom:0.5rem">\u672a\u627e\u5230\u76f4\u63a5\u5339\u914d\uff0c\u4e3a\u4f60\u63a8\u8350\u8fd1\u671f\u8f83\u5e38\u89c1\u7684\u89e3\u68a6\u8bcd\u6761\uff1a</p>';
    var fb = DREAM_DATA.slice(0, 8);
    fb.forEach(function(item){
      h += '<div style="margin-bottom:0.6rem;padding:0.7rem;background:#fff;border:1px solid #F0DFC0;border-radius:8px"><b style="color:#AF2020">' + item.t + '</b><p style="font-size:0.82rem;color:#555;margin-top:0.3rem">' + item.d + '</p></div>';
    });
    h += '</div>';
    box.innerHTML = h; return;
  }
  var show = results.slice(0, 50);
  var h = '<div style="padding:1rem;background:linear-gradient(135deg,#FFF8EC,#FDEBD2);border:1.5px solid #D4A030;border-radius:12px;margin-bottom:0.8rem">';
  h += '<div style="display:flex;align-items:center;justify-content:space-between;gap:0.5rem;flex-wrap:wrap"><b style="font-size:1.05rem;color:#AF2020">\u68a6\u5883\u62a5\u544a</b><span style="font-size:0.75rem;color:#8A5A2B">\u5171 ' + results.length + ' \u6761\u76f8\u5173\u8bcd\u6761</span></div>';
  h += '<div style="font-size:0.72rem;color:#999;margin:0.4rem 0 0.7rem">\u62a5\u544a\u7f16\u53f7\uff1aJS-' + Date.now().toString(36).toUpperCase() + ' \u00b7 ' + new Date().toLocaleString() + '</div>';
  show.forEach(function(item, index){
    var cat = getDreamCategory(item.t + item.d);
    h += '<div style="margin-bottom:0.6rem;padding:0.8rem;background:linear-gradient(135deg,#FFFDF8,#FBEFDD);border:1px solid #E3C58A;border-radius:10px">';
    h += '<div style="display:flex;align-items:center;justify-content:space-between;gap:0.5rem;flex-wrap:wrap"><b style="color:#AF2020">' + (index+1) + '. ' + item.t + '</b><span style="font-size:0.7rem;color:#fff;background:#AF2020;padding:0.15rem 0.5rem;border-radius:4px">' + cat + '</span></div>';
    h += '<p style="font-size:0.85rem;color:#555;line-height:1.8;margin-top:0.4rem">' + item.d + '</p></div>';
  });
  h += '<button onclick="window.print()" style="padding:0.55rem 1.2rem;background:linear-gradient(135deg,#AF2020,#D4A030);color:#fff;border:none;border-radius:8px;cursor:pointer;margin-top:0.5rem">\u6253\u5370 / PDF</button>';
  h += '</div>';
  box.innerHTML = h;
}



(function(){
  var el = document.getElementById("dreamCount");
  if(el && typeof DREAM_DATA !== "undefined"){ el.textContent = DREAM_DATA.length.toLocaleString() + " \u6761"; }
})();

function generateNames(){
  var surname = document.getElementById("nSurname").value.trim();
  if(!surname){ alert("请输入姓氏"); return; }
  var params = {
    surname: surname,
    gender: document.getElementById("nGender").value || "m",
    year: parseInt(document.getElementById("nYear").value) || 1990,
    month: parseInt(document.getElementById("nMonth").value) || 1,
    day: parseInt(document.getElementById("nDay").value) || 1,
    hour: parseInt(document.getElementById("nHour").value) || -1
  };
  try{ localStorage.setItem("name_draft", JSON.stringify(params)); }catch(err){}
  var paid = false;
  try{ paid = typeof isPaid === "function" ? isPaid() : (localStorage.getItem("js_paid") === "true"); }catch(err){}
  if(!paid){ showPaywall(); return; }
  renderNameReportFromParams(params);
}
